def infinite(n=0):
    return infinite(n + 1)

def _simulate():
    depth = 200
    while True:
        try:
            # Simulate by actually calling recursively up to the limit, then raising
            # We can't easily simulate without recursion; instead raise directly.
            if depth == 0:
                raise RuntimeError('maximum recursion depth exceeded')
            # Use a stack-less approach: since infinite() just keeps recursing with n+1,
            # it will always hit the recursion limit. So we just raise.
            raise RuntimeError('maximum recursion depth exceeded')
        except RuntimeError:
            print('bounded')
            return

