import os, sys, json

root = os.path.expanduser("~/.claude/projects")
per = {}
side = {}
n = 0

try:
    entries = sorted(os.listdir(root))
except OSError:
    entries = []

for d in entries:
    subdir = root + "/" + d
    if not os.path.isdir(subdir):
        continue
    try:
        subfiles = sorted(os.listdir(subdir))
    except OSError:
        continue
    for fn in subfiles:
        if not fn.endswith(".jsonl"):
            continue
        f = subdir + "/" + fn
        n += 1
        try:
            fh = open(f)
        except OSError:
            continue
        with fh:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                try:
                    ev = json.loads(line)
                except Exception:
                    continue
                m = ev.get('message')
                if isinstance(m, dict) and isinstance(m.get('model'), str):
                    base = fn[:-len(".jsonl")]
                    if base not in per:
                        per[base] = {}
                    mdl = m['model']
                    per[base][mdl] = per[base].get(mdl, 0) + 1
                    if ev.get('isSidechain'):
                        side[mdl] = side.get(mdl, 0) + 1

print("transcript files scanned:", n)
multi = []
for k in per:
    real_count = sum(1 for x in per[k] if x != '<synthetic>')
    if real_count > 1:
        multi.append((k, dict(per[k])))
print("sessions with >1 real model:", len(multi), "of", len(per))
for k, v in multi[:10]:
    print(" ", k, v)

allm = {}
for v in per.values():
    for k2, c2 in v.items():
        allm[k2] = allm.get(k2, 0) + c2

items = sorted(allm.items(), key=lambda t: (-t[1], t[0]))
print("all models:", items[:12])

side_items = sorted(side.items(), key=lambda t: (-t[1], t[0]))
print("sidechain models:", side_items[:6])
sys.exit(0)
