MARKS=[0x300,0x301,0x302,0x303,0x304,0x306,0x307,0x308,0x30a,0x30b,0x30c,0x327,0x328]
OURS={}
for cp in range(0xC0,0x180):
    d=u.decomposition(chr(cp))
    if d and not d.startswith('<'):
        p=d.split(); OURS[(int(p[0],16),int(p[1],16))]=cp
pairs={}
for cp in range(0x110000):
    if 0xD800<=cp<0xE000: continue
    d=u.decomposition(chr(cp))
    if d and not d.startswith('<'):
        p=d.split()
        if len(p)==2:
            b=int(p[0],16); m=int(p[1],16)
            if m in MARKS:
                # authoritative: does it really compose?
                if u.normalize('NFC',chr(b)+chr(m))==chr(cp):
                    pairs[(b,m)]=cp
danger={k:v for k,v in pairs.items() if k not in OURS}
print("total composing pairs with our marks:",len(pairs),"ours:",len(OURS),"danger:",len(danger))
bs=sorted({b for b,m in danger})
print("distinct danger bases:",len(bs))
print("bases:", " ".join(hex(b) for b in bs[:80]))
# per mark
from collections import Counter
print(Counter(hex(m) for b,m in danger))

