import re

# We need to avoid \W, \w in regex on non-ASCII subjects/patterns
# Let's manually implement the logic

def is_word_char(ch):
    """Return True if ch is a word character (letter, digit, or underscore)."""
    return ch.isalnum() or ch == '_'

def sub_non_word_with_dash(s):
    """Replace sequences of non-word characters with '-'."""
    result = []
    in_sequence = False
    for ch in s:
        if not is_word_char(ch):
            if not in_sequence:
                result.append('-')
                in_sequence = True
        else:
            result.append(ch)
            in_sequence = False
    return ''.join(result)

def findall_words(s):
    """Find all word character sequences."""
    words = []
    current = []
    for ch in s:
        if is_word_char(ch):
            current.append(ch)
        else:
            if current:
                words.append(''.join(current))
                current = []
    if current:
        words.append(''.join(current))
    return words

def finditer_spans(pattern, s):
    """Find all occurrences of pattern in s and return their spans."""
    spans = []
    start = 0
    while True:
        idx = s.find(pattern, start)
        if idx == -1:
            break
        spans.append((idx, idx + len(pattern)))
        start = idx + 1
    return spans

print(sub_non_word_with_dash("räksmörgås och öl"))
