    return not is_word_char_unicode(c)

# First line: re.sub(r"\W+", "-", "räksmörgås och öl")
def sub_wplus(text):
    result = []
    i = 0
    n = len(text)
    while i < n:
        if is_non_word_char_unicode(text[i]):
            j = i
            while j < n and is_non_word_char_unicode(text[j]):
                j += 1
            result.append('-')
            i = j
        else:
            result.append(text[i])
            i += 1
    return ''.join(result)

