def parse_url(u):
    # Split scheme
    if "://" in u:
        rest = u.split("://", 1)[1]
    else:
        rest = u
    if "/" in rest:
        netloc, path_query = rest.split("/", 1)
        path_query = "/" + path_query
    else:
        netloc = ""
        path_query = ""
    if "?" in path_query:
        path, query = path_query.split("?", 1)
    else:
        path = path_query
        query = ""
    return netloc, path, query


def parse_qs(query, keep_blank_values=False):
    """Minimal parse_qs for simple key=value&key2=value2 queries."""
    result = {}
    if not query:
        return result
    pairs = query.split("&")
    for pair in pairs:
        if not pair:
            continue
        if "=" in pair:
            key, value = pair.split("=", 1)
        else:
            key = pair
            value = ""
        if key not in result:
            result[key] = []
        result[key].append(value)
    return result


