            k, v = part.split("=", 1)
        else:
            k, v = part, ""
        pairs.append((k, v))

def unquote(s):
    out = []
    i = 0
    while i < len(s):
        c = s[i]
        if c == "%":
            if i + 2 < len(s) + 1 and i + 2 <= len(s) - 1:
                hexc = s[i+1:i+3]
                try:
                    code = int(hexc, 16)
                    out.append(chr(code))
                    i += 3
                    continue
                except ValueError:
                    pass
            out.append(c)
            i += 1
        elif c == "+":
            out.append(" ")
            i += 1
        else:
            out.append(c)
            i += 1
    return "".join(out)

qs = {}
for k, v in pairs:
    kk = unquote(k)
    vv = unquote(v)
    qs.setdefault(kk, []).append(vv)

