def find_jsonl(base):
    try:
        entries=os.listdir(base)
    except Exception:
        return []
    res=[]
    for e in entries:
        p=base+"/"+e
        try:
            if os.path.isdir(p):
                res.extend(find_jsonl(p))
            else:
                if e.endswith(".jsonl"):
                    res.append(p)
        except Exception:
            pass
