top_path_parts = len(os.path.expanduser('~/.claude/projects').split('/'))
top = [f for f in files if f.count('/') == top_path_parts + 1]
print("total jsonl:", len(files))

c = {}
ctop = {}
csub = {}
persess = {}
side = 0

for f in files:
    sub = '/subagents/' in f
    for line in open(f, errors='replace'):
        line = line.strip()
        if not line:
            continue
        try:
            o = json.loads(line)
        except Exception:
            continue
        if o.get('type') != 'assistant':
            continue
        m = o.get('message')
        if not isinstance(m, dict):
            continue
        mod = m.get('model')
        if not mod:
            continue
        c[mod] = c.get(mod, 0) + 1
        (csub if sub else ctop)[mod] = (csub if sub else ctop).get(mod, 0) + 1
        persess.setdefault(f, {})
        persess[f][mod] = persess[f].get(mod, 0) + 1
        if o.get('isSidechain'):
            side += 1

print("=== ALL message.model values ===")
for k, v in sorted(c.items(), key=lambda x: (-x[1], x[0])):
    print(f"{v:8d}  {k}")
print("=== main-transcript only ===")
for k, v in sorted(ctop.items(), key=lambda x: (-x[1], x[0])):
    print(f"{v:8d}  {k}")
print("=== subagent files only ===")
for k, v in sorted(csub.items(), key=lambda x: (-x[1], x[0])):
    print(f"{v:8d}  {k}")
print("isSidechain=true assistant records:", side)
print("=== per-file model mixes (files with >1) ===")
for f, cc in persess.items():
    if len(cc) > 1:
        print(" ", f.replace(os.path.expanduser('~'), '~'), dict(cc))
