import json,glob,collections,os

def expanduser(p):
    if p and p[0] == '~':
        home = os.environ.get('HOME', '')
        return home + p[1:]
    return p

files = sorted(glob.glob(expanduser('~/.claude/projects/**/*.jsonl'), recursive=True))
projects_dir = expanduser('~/.claude/projects')
depth = len(projects_dir.split('/')) + 1
top = [f for f in files if f.count('/') == depth]
print("total jsonl:", len(files))

c = collections.Counter()
ctop = collections.Counter()
csub = collections.Counter()
persess = {}
side = 0
for f in files:
    sub = '/subagents/' in f
    for line in open(f, errors='replace'):
        line = line.strip()
        if not line:
            continue
        try:
            o = json.loads(line)
        except Exception:
            continue
        if o.get('type') != 'assistant':
            continue
        m = o.get('message')
        if not isinstance(m, dict):
            continue
        mod = m.get('model')
        if not mod:
            continue
        c[mod] += 1
        (csub if sub else ctop)[mod] += 1
        persess.setdefault(f, collections.Counter())[mod] += 1
        if o.get('isSidechain'):
            side += 1

print("=== ALL message.model values ===")
for k, v in c.most_common():
    print(f"{v:8d}  {k}")
print("=== main-transcript only ===")
for k, v in ctop.most_common():
    print(f"{v:8d}  {k}")
print("=== subagent files only ===")
for k, v in csub.most_common():
    print(f"{v:8d}  {k}")
print("isSidechain=true assistant records:", side)
print("=== per-file model mixes (files with >1) ===")
for f, cc in persess.items():
    if len(cc) > 1:
        print(" ", f.replace(expanduser('~'), '~'), dict(cc))
